import { z } from "zod";

import {
  ChartColorTokenSchema,
  FormatOptionsSchema,
  GranularitySchema,
  MemberSchema,
  VarRefSchema,
  DateRangeSchema,
  type BuiltinChartFamily,
  type ChartOptions,
} from "@/spec";

/**
 * Per-family option DEFAULTS, the `familyOptions` zod schemas, and the
 * default-merge (`resolveOptions`). See docs/02-chart-options.md §4.
 *
 * Two rules the doc nails down:
 *  - Defaults are TOTAL: a `{}` familyOptions still renders a sensible chart.
 *  - Deep-merge merges objects recursively but REPLACES arrays wholesale
 *    (`referenceLines`/`columns`/`series` are predictable, never element-merged).
 */

/* ─────────────────────── shared familyOptions sub-schemas ────────────────── */

/** A reference line on the x or y axis (bar/line/area/scatter). */
export const ReferenceLineOptSchema = z
  .object({
    axis: z.enum(["x", "y"]),
    value: z.number(),
    label: z.string().optional(),
    colorToken: ChartColorTokenSchema.optional(),
  })
  .strict();
export type ReferenceLineOpt = z.infer<typeof ReferenceLineOptSchema>;

/* ─────────────────────────── per-family schemas ──────────────────────────── */

/** Overlay the immediately-preceding equal-length period as a muted companion series. */
const ComparePreviousSchema = z.boolean().optional();

export const BarFamilyOptionsSchema = z
  .object({
    showValueLabels: z.boolean().optional(),
    referenceLines: z.array(ReferenceLineOptSchema).optional(),
    comparePrevious: ComparePreviousSchema,
  })
  .strict();
export type BarFamilyOptions = z.infer<typeof BarFamilyOptionsSchema>;

const CurveSchema = z.enum(["linear", "monotone", "step", "natural"]);

export const LineFamilyOptionsSchema = z
  .object({
    curve: CurveSchema.optional(),
    dots: z.union([z.boolean(), z.literal("active")]).optional(),
    connectNulls: z.boolean().optional(),
    chrome: z.enum(["full", "none"]).optional(),
    referenceLines: z.array(ReferenceLineOptSchema).optional(),
    showValueLabels: z.boolean().optional(),
    comparePrevious: ComparePreviousSchema,
  })
  .strict();
export type LineFamilyOptions = z.infer<typeof LineFamilyOptionsSchema>;

export const AreaFamilyOptionsSchema = z
  .object({
    curve: CurveSchema.optional(),
    connectNulls: z.boolean().optional(),
    dots: z.boolean().optional(),
    referenceLines: z.array(ReferenceLineOptSchema).optional(),
    comparePrevious: ComparePreviousSchema,
  })
  .strict();
export type AreaFamilyOptions = z.infer<typeof AreaFamilyOptionsSchema>;

export const PieFamilyOptionsSchema = z
  .object({
    innerRadiusPct: z.number().optional(),
    showLabels: z.enum(["none", "value", "percent", "name"]).optional(),
    centerLabel: z
      .object({ value: z.string().optional(), label: z.string().optional() })
      .strict()
      .optional(),
    maxSlices: z.number().optional(),
  })
  .strict();
export type PieFamilyOptions = z.infer<typeof PieFamilyOptionsSchema>;

export const ScatterFamilyOptionsSchema = z
  .object({
    x: MemberSchema,
    y: MemberSchema,
    size: MemberSchema.optional(),
    groupBy: MemberSchema.optional(),
    referenceLines: z.array(ReferenceLineOptSchema).optional(),
  })
  .strict();
export type ScatterFamilyOptions = z.infer<typeof ScatterFamilyOptionsSchema>;

export const KpiFamilyOptionsSchema = z
  .object({
    display: z.enum(["number", "gauge"]).optional(),
    measure: MemberSchema,
    comparison: z
      .object({
        mode: z.enum(["previousPeriod", "value"]),
        value: z.union([MemberSchema, z.number()]).optional(),
        showAsPercent: z.boolean().optional(),
        goodDirection: z.enum(["up", "down"]).optional(),
      })
      .strict()
      .optional(),
    /** Inline AREA trend under the headline. TIED to the KPI: its measure defaults to
     *  `measure` and its time dimension / range to the KPI's own query — only the
     *  granularity (the trend bucket) is sparkline-specific. Its area is colored by the
     *  same good/bad direction as the comparison delta (see `goodDirection`). */
    sparkline: z
      .object({
        member: MemberSchema.optional(),
        timeDimension: MemberSchema.optional(),
        granularity: z.union([GranularitySchema, VarRefSchema]).optional(),
        dateRange: z.union([DateRangeSchema, VarRefSchema]).optional(),
      })
      .strict()
      .optional(),
    /** The change direction that counts as "good" — drives BOTH the comparison delta
     *  color and the sparkline area color. Configured once for the KPI. */
    goodDirection: z.enum(["up", "down"]).optional(),
    gauge: z
      .object({
        min: z.number().optional(),
        max: z.number(),
        thresholds: z
          .array(z.object({ at: z.number(), colorToken: ChartColorTokenSchema }).strict())
          .optional(),
      })
      .strict()
      .optional(),
  })
  .strict();
export type KpiFamilyOptions = z.infer<typeof KpiFamilyOptionsSchema>;

export const TableColumnOptSchema = z
  .object({
    member: MemberSchema,
    label: z.string().optional(),
    format: FormatOptionsSchema.optional(),
    align: z.enum(["left", "right", "center"]).optional(),
    width: z.number().optional(),
    hidden: z.boolean().optional(),
  })
  .strict();
export type TableColumnOpt = z.infer<typeof TableColumnOptSchema>;

export const CondFormatRuleSchema = z
  .object({
    member: MemberSchema,
    when: z
      .object({
        op: z.enum(["gt", "lt", "gte", "lte", "eq"]),
        value: z.number(),
      })
      .strict(),
    colorToken: ChartColorTokenSchema.optional(),
  })
  .strict();
export type CondFormatRule = z.infer<typeof CondFormatRuleSchema>;

export const TableFamilyOptionsSchema = z
  .object({
    columns: z.array(TableColumnOptSchema).optional(),
    pageSize: z.number().optional(),
    conditionalFormat: z.array(CondFormatRuleSchema).optional(),
    // REMOVED in v4 — `sortable`, `stickyHeader`, `showRowNumbers` and `rowHeight`.
    // Sorting and a pinned header are what makes a table a table, so they are always
    // on; density follows the row count; row numbers say nothing about the data.
  })
  .strict();
export type TableFamilyOptions = z.infer<typeof TableFamilyOptionsSchema>;

/**
 * `heatmap` options — deliberately minimal (simplicity over knobs). The grid's
 * members (x dimension, y dimension, value measure) live in the generic `mapping`
 * envelope (category = x, pivot = y, value = measure), NOT here.
 */
export const HeatmapFamilyOptionsSchema = z
  .object({
    /** The single-hue ramp token; cells shade light→dark within this hue. */
    colorToken: ChartColorTokenSchema.optional(),
    // REMOVED in v4 — `showValues`. The renderer prints in-cell numbers when the grid
    // is small enough to read them (≤100 cells), which is the answer every time.
  })
  .strict();
export type HeatmapFamilyOptions = z.infer<typeof HeatmapFamilyOptionsSchema>;

/**
 * The builtin family → `familyOptions` zod schemas (validated AFTER default-merge).
 * RAW DATA ONLY — this module is a registry leaf (the family registry seeds itself
 * from here; routing the other way would create a module cycle). The public
 * accessor that tolerates host families lives on the registry
 * ({@link import("./familyRegistry").getFamilyOptionsSchema}).
 */
export const BUILTIN_FAMILY_OPTION_SCHEMAS = {
  bar: BarFamilyOptionsSchema,
  line: LineFamilyOptionsSchema,
  area: AreaFamilyOptionsSchema,
  pie: PieFamilyOptionsSchema,
  scatter: ScatterFamilyOptionsSchema,
  heatmap: HeatmapFamilyOptionsSchema,
  kpi: KpiFamilyOptionsSchema,
  table: TableFamilyOptionsSchema,
} satisfies Record<BuiltinChartFamily, z.ZodTypeAny>;

/* ──────────────────────────────── defaults ───────────────────────────────── */

/** A family default = an envelope slice + a complete familyOptions object. */
export interface FamilyDefault {
  envelope: Partial<ChartOptions>;
  familyOptions: Record<string, unknown>;
}

/**
 * Total defaults per family (docs/02-chart-options.md §4). Stored specs carry
 * only overrides, deep-merged over these. Rationale per family is in the doc.
 */
export const BUILTIN_DEFAULTS = {
  bar: {
    envelope: {
      orientation: "vertical",
      stackMode: "none",
      legend: { show: true, position: "bottom" },
      tooltip: { show: true, indicator: "dot" },
      format: { kind: "auto" },
    },
    familyOptions: {
      showValueLabels: false,
    } satisfies BarFamilyOptions,
  },
  line: {
    envelope: {
      legend: { show: true, position: "bottom" },
      tooltip: { show: true, indicator: "line" },
      format: { kind: "auto" },
    },
    familyOptions: {
      curve: "monotone",
      dots: "active",
      connectNulls: false,
      chrome: "full",
    } satisfies LineFamilyOptions,
  },
  area: {
    // No static stackMode: the area renderer defaults it SHAPE-AWARELY (a color-split
    // pivot stacks as parts of a whole; multiple independent measures overlap instead of
    // summing into a misleading band). An explicit spec stackMode always wins.
    envelope: {
      legend: { show: true, position: "bottom" },
      tooltip: { show: true, indicator: "dot" },
      format: { kind: "auto" },
    },
    familyOptions: {
      curve: "monotone",
      connectNulls: false,
    } satisfies AreaFamilyOptions,
  },
  pie: {
    envelope: {
      // Was `"right"`, which the renderer has always drawn at the bottom.
      legend: { show: true, position: "bottom" },
      tooltip: { show: true, indicator: "dot" },
      format: { kind: "auto" },
    },
    familyOptions: {
      innerRadiusPct: 0,
      showLabels: "percent",
      maxSlices: 8,
    } satisfies PieFamilyOptions,
  },
  scatter: {
    envelope: {
      legend: { show: true, position: "bottom" },
      tooltip: { show: true, indicator: "dot" },
      format: { kind: "auto" },
    },
    // x/y are required from the spec, so they are absent from the default skeleton.
    familyOptions: {} as Record<string, unknown>,
  },
  kpi: {
    envelope: { format: { kind: "auto" } },
    // measure is required from the spec.
    familyOptions: { display: "number" } as Record<string, unknown>,
  },
  heatmap: {
    // No legend envelope: the heatmap has no series legend (color encodes value).
    envelope: {
      tooltip: { show: true, indicator: "dot" },
      format: { kind: "auto" },
    },
    familyOptions: {
      colorToken: "chart-1",
    } satisfies HeatmapFamilyOptions,
  },
  table: {
    envelope: {},
    familyOptions: {
      pageSize: 25,
    } satisfies TableFamilyOptions,
  },
} satisfies Record<BuiltinChartFamily, FamilyDefault>;

/* ──────────────────────────────── merge ──────────────────────────────────── */

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/**
 * Deep-merge `override` over `base`: objects recurse, **arrays replace wholesale**,
 * scalars/undefined-aware (an explicit `undefined` does not clobber a base value).
 */
export function deepMerge<T>(base: T, override: unknown): T {
  if (override === undefined) return base;
  if (!isPlainObject(base) || !isPlainObject(override)) {
    // Arrays + scalars: the override wins outright (arrays are never element-merged).
    return override as T;
  }
  const out: Record<string, unknown> = { ...base };
  for (const key of Object.keys(override)) {
    const ov = override[key];
    if (ov === undefined) continue;
    out[key] = key in base ? deepMerge(base[key], ov) : ov;
  }
  return out as T;
}

/** The neutral default for a family that has none registered (no envelope, no opts). */
export const EMPTY_FAMILY_DEFAULT: FamilyDefault = { envelope: {}, familyOptions: {} };

/**
 * Resolve a chart's options against a family default: deep-merge the family's
 * envelope defaults under the spec's envelope, and the family's familyOptions
 * defaults under the spec's familyOptions. Arrays (referenceLines/columns/series)
 * are replaced, not merged.
 *
 * `resolveOptionsWith` takes the default EXPLICITLY so this module stays a registry
 * leaf (no import of the family registry). The public {@link
 * import("./familyRegistry").resolveOptions} looks the default up from the registry
 * — supporting host families — and delegates here.
 */
export function resolveOptionsWith(options: ChartOptions, d: FamilyDefault): ChartOptions {
  const merged = deepMerge<ChartOptions>({ ...(d.envelope as ChartOptions) }, options);
  return {
    ...merged,
    familyOptions: deepMerge(
      { ...d.familyOptions },
      options.familyOptions ?? {},
    ) as Record<string, unknown>,
  };
}
